-- Fase 87: Enterprise Risk Management. Governance only; domain systems remain execution owners.
-- Supabase CLI was unavailable in this workspace, so the sequential migration name is recorded explicitly.
-- quality: allow-nonconcurrent-index reason=new-empty-enterprise-risk-tables
alter table public.plans add column if not exists enterprise_risk_management_enabled boolean not null default false;
alter table public.plans add column if not exists third_party_risk_enabled boolean not null default false;
alter table public.plans add column if not exists risk_kri_monitoring_enabled boolean not null default false;
alter table public.plans add column if not exists risk_concentration_analysis_enabled boolean not null default false;

create table public.risk_member_permissions(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{risk:view}',scope_types text[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.risk_categories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,parent_id uuid references public.risk_categories(id),description text,owner_role text,status text not null default 'active' check(status in('active','inactive','archived')),created_at timestamptz not null default now(),unique(organization_id,key),check(parent_id is null or parent_id<>id));
create table public.risk_matrix_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,version text not null,likelihood_scale jsonb not null,impact_scale jsonb not null,risk_levels jsonb not null,matrix_cells jsonb not null,overall_impact_policy text not null default 'highest_dimension',status text not null default 'draft' check(status in('draft','active','retired')),effective_from timestamptz,effective_until timestamptz,published_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,name,version));
create table public.risk_impact_dimensions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,scale jsonb not null default '[]',financial_ranges jsonb,status text not null default 'active',created_at timestamptz not null default now(),unique(organization_id,key));
create table public.enterprise_risks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_key text not null,title text not null,description text not null,category_id uuid not null references public.risk_categories(id),source_type text not null check(source_type in('manual','incident','audit','continuity','supplier','security','quality','data','integration','finance','automated_candidate')),source_ref text,scope_type text not null check(scope_type in('service','store','region','supplier','provider','integration','asset','process','project','data_asset','product','contract','network','platform')),scope_id text,owner_user_id uuid references auth.users(id),owner_role text,status text not null default 'draft' check(status in('draft','active','monitoring','treatment_in_progress','accepted','closed','archived')),risk_state text not null default 'identified' check(risk_state in('identified','assessed','controlled','accepted','escalated','realized','closed')),identified_at timestamptz not null default now(),review_due_at timestamptz,closed_at timestamptz,closure_rationale text,sensitive boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,risk_key));
create table public.risk_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,version integer not null check(version>0),assessment_type text not null check(assessment_type in('initial','periodic','post_incident','post_control_change','post_treatment','ad_hoc')),likelihood_level text not null,impact_level text not null,inherent_risk_level text not null,impact_dimensions jsonb not null default '{}',control_effectiveness text not null check(control_effectiveness in('effective','partially_effective','ineffective','untested','unknown')),residual_likelihood_level text not null,residual_impact_level text not null,residual_risk_level text not null,matrix_definition_id uuid not null references public.risk_matrix_definitions(id),methodology_version text not null,rationale text not null,assessed_by uuid not null references auth.users(id),assessed_at timestamptz not null default now(),published_at timestamptz,created_at timestamptz not null default now(),unique(risk_id,version));
create table public.risk_controls(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,description text not null,control_type text not null check(control_type in('preventive','detective','corrective','recovery','compensating')),control_nature text not null check(control_nature in('technical','procedural','contractual','organizational','financial','physical','data','monitoring')),owner_user_id uuid references auth.users(id),owner_role text,frequency text,automation_level text not null check(automation_level in('manual','semi_automated','automated')),status text not null default 'designed' check(status in('designed','implemented','active','degraded','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,key));
create table public.risk_control_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,control_id uuid not null references public.risk_controls(id) on delete cascade,relationship text not null check(relationship in('primary','supporting','compensating')),expected_effect text not null,criticality text not null check(criticality in('low','medium','high','critical')),created_at timestamptz not null default now(),unique(risk_id,control_id));
create table public.control_tests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,control_id uuid not null references public.risk_controls(id) on delete cascade,test_type text not null check(test_type in('design','operating_effectiveness','technical_validation','sample_review','restore_test','reconciliation','audit')),scope jsonb not null default '{}',period_start timestamptz,period_end timestamptz,result text not null check(result in('pass','partial','fail','inconclusive','not_tested')),evidence_refs jsonb not null default '[]',tester_id uuid not null references auth.users(id),tested_at timestamptz not null,next_test_due_at timestamptz,created_at timestamptz not null default now());
create table public.risk_evidence_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid references public.enterprise_risks(id) on delete cascade,control_id uuid references public.risk_controls(id) on delete cascade,control_test_id uuid references public.control_tests(id) on delete cascade,evidence_type text not null check(evidence_type in('incident','audit','test','report','metric','document','contract','restore','reconciliation','certification_internal')),source_domain text not null,source_ref text not null,collected_at timestamptz not null,valid_until timestamptz,metadata_redacted jsonb not null default '{}',created_at timestamptz not null default now(),check(risk_id is not null or control_id is not null or control_test_id is not null));
create table public.risk_treatments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,strategy text not null check(strategy in('mitigate','avoid','transfer','accept','monitor')),target_residual_level text,owner_user_id uuid not null references auth.users(id),due_date date,status text not null default 'proposed' check(status in('proposed','approved','in_progress','blocked','completed','cancelled')),rationale text not null,task_refs jsonb not null default '[]',reassessment_id uuid references public.risk_assessments(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status<>'completed' or reassessment_id is not null));
create table public.risk_acceptances(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,accepted_residual_level text not null,reason text not null,accepted_by uuid not null references auth.users(id),approval_ref text not null,accepted_at timestamptz not null default now(),expires_at timestamptz,review_conditions text,status text not null default 'pending' check(status in('pending','active','expired','revoked','superseded')),created_at timestamptz not null default now(),check(accepted_residual_level not in('high','critical') or expires_at is not null));
create table public.risk_appetite_statements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,version integer not null check(version>0),category_id uuid references public.risk_categories(id),scope_type text,scope_id text,maximum_residual_level text not null,statement text not null,tolerances jsonb not null default '{}',status text not null default 'draft' check(status in('draft','active','retired')),approved_by uuid references auth.users(id),effective_from timestamptz,effective_until timestamptz,created_at timestamptz not null default now(),unique(organization_id,version,category_id,scope_type,scope_id));
create table public.key_risk_indicators(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid references public.enterprise_risks(id) on delete cascade,category_id uuid references public.risk_categories(id),metric_ref text not null,warning_threshold numeric,critical_threshold numeric,direction text not null check(direction in('above','below')),evaluation_window text not null,owner_user_id uuid references auth.users(id),status text not null default 'active',last_state text not null default 'unknown' check(last_state in('normal','warning','critical','unknown')),last_evaluated_at timestamptz,created_at timestamptz not null default now(),check(risk_id is not null or category_id is not null));
create table public.risk_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid references public.enterprise_risks(id) on delete set null,source text not null,event_type text not null,severity text not null,occurred_at timestamptz not null,source_ref text not null,description text not null,status text not null default 'open',created_at timestamptz not null default now(),unique(organization_id,source,source_ref,event_type));
create table public.risk_candidates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,source text not null check(source in('incident','audit','noc','continuity','supplier','data_quality','security','integration','reliability','finance','quality')),source_ref text not null,title text not null,description text,category_hint text,severity_hint text,status text not null default 'pending_review' check(status in('pending_review','approved','rejected','converted')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,converted_risk_id uuid references public.enterprise_risks(id),created_at timestamptz not null default now());
create unique index risk_candidates_open_source_idx on public.risk_candidates(organization_id,source,source_ref) where status in('pending_review','approved');
create table public.third_party_risk_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,third_party_ref text not null,relationship_type text not null check(relationship_type in('supplier','technology_provider','payment_provider','marketplace','logistics_provider','consultant','integration_partner','custom')),criticality text not null,data_access_level text not null,operational_dependency text not null,substitutability text not null,concentration_scope text,status text not null default 'active',continuity_profile_ref text,exit_plan_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,third_party_ref));
create table public.third_party_risk_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.third_party_risk_profiles(id) on delete cascade,version integer not null,dimensions jsonb not null,evidence_refs jsonb not null default '[]',rationale text not null,assessed_by uuid not null references auth.users(id),assessed_at timestamptz not null default now(),unique(profile_id,version));
create table public.risk_dependencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,related_risk_id uuid not null references public.enterprise_risks(id) on delete cascade,dependency_type text not null check(dependency_type in('causes','amplifies','depends_on','shares_control','shares_dependency')),created_at timestamptz not null default now(),unique(risk_id,related_risk_id,dependency_type),check(risk_id<>related_risk_id));
create table public.risk_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete cascade,review_type text not null check(review_type in('periodic','incident','control_failure','kri_breach','major_change','treatment_completion')),previous_assessment_id uuid references public.risk_assessments(id),new_assessment_id uuid references public.risk_assessments(id),reviewer_id uuid not null references auth.users(id),review_date timestamptz not null default now(),conclusions text not null,actions jsonb not null default '[]',created_at timestamptz not null default now());
create table public.risk_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state_redacted jsonb,after_state_redacted jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create index enterprise_risks_org_status_idx on public.enterprise_risks(organization_id,status,risk_state,review_due_at);
create index risk_assessments_risk_idx on public.risk_assessments(risk_id,version desc);
create index risk_controls_org_status_idx on public.risk_controls(organization_id,status);
create index control_tests_control_idx on public.control_tests(control_id,tested_at desc);
create index risk_treatments_org_due_idx on public.risk_treatments(organization_id,status,due_date);
create index risk_acceptances_org_expiry_idx on public.risk_acceptances(organization_id,status,expires_at);
create index kri_org_state_idx on public.key_risk_indicators(organization_id,last_state,last_evaluated_at);
create index risk_events_org_time_idx on public.risk_events(organization_id,occurred_at desc);
create index third_party_risk_org_idx on public.third_party_risk_profiles(organization_id,criticality,status);
create index risk_audit_org_idx on public.risk_audit_events(organization_id,created_at desc);
create index risk_categories_parent_idx on public.risk_categories(parent_id);
create index enterprise_risks_category_idx on public.enterprise_risks(category_id);
create index risk_assessments_matrix_idx on public.risk_assessments(matrix_definition_id);
create index risk_control_mappings_control_idx on public.risk_control_mappings(control_id);
create index risk_evidence_risk_idx on public.risk_evidence_links(risk_id);
create index risk_evidence_control_idx on public.risk_evidence_links(control_id);
create index risk_evidence_test_idx on public.risk_evidence_links(control_test_id);
create index risk_treatments_risk_idx on public.risk_treatments(risk_id);
create index risk_treatments_reassessment_idx on public.risk_treatments(reassessment_id);
create index risk_acceptances_risk_idx on public.risk_acceptances(risk_id);
create index risk_appetite_category_idx on public.risk_appetite_statements(category_id);
create index kri_risk_idx on public.key_risk_indicators(risk_id);
create index kri_category_idx on public.key_risk_indicators(category_id);
create index risk_events_risk_idx on public.risk_events(risk_id);
create index risk_candidates_converted_idx on public.risk_candidates(converted_risk_id);
create index risk_dependencies_related_idx on public.risk_dependencies(related_risk_id);
create index risk_reviews_previous_idx on public.risk_reviews(previous_assessment_id);
create index risk_reviews_new_idx on public.risk_reviews(new_assessment_id);

