create view public.enterprise_risk_portfolio with(security_invoker=true) as
select r.organization_id,r.id,r.risk_key,r.title,r.status,r.risk_state,r.owner_user_id,r.review_due_at,a.inherent_risk_level,a.residual_risk_level,a.control_effectiveness,a.methodology_version,a.assessed_at,
case when r.owner_user_id is null then true else false end as owner_missing,
case when exists(select 1 from public.risk_acceptances x where x.risk_id=r.id and x.status='active' and (x.expires_at is null or x.expires_at>now())) then true else false end as acceptance_active
from public.enterprise_risks r left join lateral(select * from public.risk_assessments a where a.risk_id=r.id order by a.version desc limit 1)a on true;

do $$ declare t text; begin foreach t in array array['risk_member_permissions','risk_categories','risk_matrix_definitions','risk_impact_dimensions','enterprise_risks','risk_assessments','risk_controls','risk_control_mappings','control_tests','risk_evidence_links','risk_treatments','risk_acceptances','risk_appetite_statements','key_risk_indicators','risk_events','risk_candidates','third_party_risk_profiles','third_party_risk_assessments','risk_dependencies','risk_reviews','risk_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;end $$;
revoke all on public.enterprise_risk_portfolio from public,anon,authenticated;
grant select on public.enterprise_risk_portfolio to service_role;

